const elementOverrides = process.env.E2E_NAV_ELEMENT_ICONS
if (elementOverrides) {
  const overrideMap = JSON.parse(elementOverrides)
  await page.evaluate((icons) => {
    for (const [title, key] of Object.entries(icons)) {
      const item = [...document.querySelectorAll('.top-nav .nav-item')]
        .find((entry) => entry.querySelector('.nav-text')?.textContent.trim() === title)
      const icon = item?.querySelector('.nav-item__icon')
      if (!icon || icon.tagName.toLowerCase() !== 'i') continue
      icon.className = `nav-item__icon nav-item__icon--element el-icon-${key}`
    }
  }, overrideMap)
  console.log(`[navbar-visual] Element overrides=${Object.keys(overrideMap).length}`)
}
